        // Precondition: ensure contract is initialized so SetMinSum would revert in original
        c.Initialized();
        // read MinSum before calling Collect
        uint before = c.MinSum();
        // call Collect which in the mutant may lead to MinSum changing indirectly
        c.Collect(am);
        // read MinSum after
        uint after = c.MinSum();
        // In original contract, after initialization MinSum cannot change as SetMinSum would revert
        assert(after == before);
    }
