contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, uint sendAmount, uint collectAmount) public payable {
        require(address(this).balance >= sendAmount);
        // Ensure contract is initialized so original contract forbids changing MinSum
        c.Initialized();
        // Record MinSum before
        uint before = c.MinSum();
        // Call Collect as the test sequence (we call from this contract; msg.sender will be this contract)
        // First, deposit some funds for this test address so Collect can potentially send out funds
        // Use fallback/Put by sending Ether
        c.Put{value: sendAmount}(0);
        // Now attempt Collect which in the mutant may allow MinSum to be altered indirectly
        c.Collect(collectAmount);
        uint after = c.MinSum();
        // General rule: after Collect, MinSum must not be less than before (can't decrease)
        assert(after >= before);
    }
    receive() external payable { }
}

