pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor to perform Put/Collect and amounts/times
    function testFuzz_property(address actor, uint96 putAmount, uint32 lockTime, uint96 collectAmount, uint newMin) public {
        // keep actor non-zero and amounts in reasonable bound
        vm.assume(actor != address(0));
        uint256 putVal = uint256(putAmount);
        uint256 collectVal = uint256(collectAmount);

        // 1) initialize contract: set MinSum to some value and set Log (use actor as log harmlessly)
        // Must call SetMinSum before Initialized; do from deployer (this)
        c.SetMinSum(1);
        c.SetLogFile(address(0));
        c.Initialized(); // now intitalized = true in reference; SetMinSum should no longer be allowed

        // 2) actor deposits funds via Put (through fallback or direct call). fund actor
        vm.deal(actor, putVal + 1 ether); // ensure actor has funds even if putVal is 0
        vm.startPrank(actor);
        if (putVal > 0) {
            c.Put{value: putVal}(lockTime);
        } else {
            // even if 0, call fallback to exercise path
            (bool s,) = address(c).call{value: 0}(abi.encodeWithSignature("Put(uint256)", lockTime));
            s; // ignore
        }
        // try Collect: only succeeds in reference if conditions met (balance>=MinSum, balance>=collectVal, time>unlockTime)
        // advance time to ensure unlockTime passed
        vm.warp(block.timestamp + uint256(lockTime) + 1);

        bool ok;
        try c.Collect(collectVal) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // After the Collect call (regardless of success), in the reference MinSum must remain 1 because SetMinSum is blocked after Initialized.
        // The mutant allows changing MinSum after Initialized; the fuzzer can set newMin and call SetMinSum externally to change it.
        // To allow the fuzzer to try to change MinSum we perform an external call from a different address (attacker) to SetMinSum with newMin.
        // Use another principal to attempt changing MinSum.
        address changer = address(uint160(uint256(keccak256(abi.encodePacked(actor, block.timestamp)))));
        vm.deal(changer, 1 ether);
        vm.prank(changer);
        // attempt to set MinSum to newMin (in reference this will revert because intitalized==true, so state stays 1)
        // in mutant this will succeed and change MinSum to newMin
        // We don't catch revert here; instead use try/catch via low-level call to ensure no test revert
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));
        success; // ignore

        // Assert the universal property: MinSum must still be 1 (the initial set value). The buggy mutant may allow it to change.
        assertTrue(c.MinSum() == 1);
    }
}

