pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor will be the caller who puts/collects, newMin is a candidate MinSum
    function testFuzz_property(address actor, uint96 putAmount, uint32 lockTime, uint96 collectAmount, uint256 newMin) public {
        // keep actor as a plausible EOA
        vm.assume(actor != address(0));
        // bound amounts to reasonable ranges to avoid trivial under/overflow and zero-value nonsense
        putAmount = uint96(bound(uint256(putAmount), 1, 1e18));
        collectAmount = uint96(bound(uint256(collectAmount), 0, uint256(putAmount)));
        lockTime = uint32(bound(uint256(lockTime), 0, 1 days));
        newMin = bound(newMin, 0, 1e30);

        // 1) set an initial MinSum value while not initialized
        uint256 initialMin = 123;
        c.SetMinSum(initialMin);
        // 2) set the LogFile to a benign one (use address(this) which is EOA-like for calls in tests)
        c.SetLogFile(address(this));
        // 3) mark initialized = true
        c.Initialized();

        // 4) actor funds the contract via Put (use prank and deal)
        vm.deal(actor, uint256(putAmount));
        vm.prank(actor);
        c.Put{value: uint256(putAmount)}(uint256(lockTime));

        // 5) fast-forward time beyond unlockTime to allow collection
        vm.warp(block.timestamp + uint256(lockTime) + 1);

        // 6) Call Collect as actor; wrap in try/catch to observe success
        bool ok;
        vm.prank(actor);
        try c.Collect(uint256(collectAmount)) {
            ok = true;
        } catch {
            ok = false;
        }

        // 7) Now attempt to change MinSum AFTER initialization using the fuzzed newMin value
        // Use an external caller (actor) to call SetMinSum; for the reference this should revert (so MinSum unchanged),
        // but the mutant removed the revert allowing MinSum to change. We check the public getter.
        vm.prank(actor);
        // We do not catch revert here; instead, read MinSum before and after attempting to set.
        uint256 before = c.MinSum();
        // Attempt set; if it reverts in reference this tx will revert the test — to avoid that we use try/catch
        try c.SetMinSum(newMin) {
            // succeeded
        } catch {
            // failed (expected for reference in many cases)
        }
        uint256 after = c.MinSum();

        // SINGLE assertion: For the reference contract, MinSum must remain equal to before for ALL admissible inputs.
        // The mutant that removed the revert can make after != before for some inputs; the fuzzer will find such inputs.
        assertTrue(after == before);
    }
}

