pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters:
    // actor: address who will put funds and call Collect
    // putAmt: amount of wei to deposit via Put (or fallback)
    // lockTime: lock time passed to Put
    // collectAmt: amount to attempt to Collect
    // newMin: value that adversary will attempt to set as MinSum after initialization
    function testFuzz_property(address actor, uint256 putAmt, uint256 lockTime, uint256 collectAmt, uint256 newMin) public {
        // Keep actor non-zero and putAmt reasonable (not overflow, some funds)
        vm.assume(actor != address(0));
        putAmt = bound(putAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        lockTime = bound(lockTime, 0, 1000000);
        newMin = bound(newMin, 0, type(uint256).max);

        // 1) Set MinSum initially (before initialization) to some value
        c.SetMinSum(1);
        // 2) mark initialized
        c.Initialized();

        // Record MinSum immediately after initialization
        uint256 minAfterInit = c.MinSum();

        // 3) actor funds the contract so Collect can be exercised
        vm.deal(actor, putAmt + 1 ether); // ensure actor has enough balance
        vm.prank(actor);
        c.Put{value: putAmt}(lockTime);

        // 4) Attempt Collect by actor (may or may not transfer depending on conditions)
        vm.prank(actor);
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // 5) After interacting (including Collect), an arbitrary caller might call SetMinSum.
        // In the reference, SetMinSum will revert because intitalized==true, so MinSum must remain unchanged.
        // We simulate a caller (different from actor) attempting to change MinSum.
        address changer = address(0xBEEF);
        vm.prank(changer);
        // Wrap in try/catch to allow both reference (revert) and mutant (succeeds) to proceed
        try c.SetMinSum(newMin) {
            // noop
        } catch {
            // noop
        }

        // Exactly one assertion: in the reference, MinSum must remain equal to minAfterInit for ALL inputs.
        // The mutant that removed the revert in SetMinSum can change MinSum, causing this assert to fail for some inputs.
        assertTrue(c.MinSum() == minAfterInit);
    }
}

