pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: actor sets MinSum and later calls Collect; newMin is a candidate malicious update
    function testFuzz_property(address actor, uint256 initialMin, uint256 newMin, uint256 deposit, uint256 collectAmt) public {
        // keep addresses usable
        vm.assume(actor != address(0));
        // keep deposit and collect within reasonable bounds to avoid trivial overflows and zero-value edgecases
        deposit = bound(deposit, 1, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        initialMin = bound(initialMin, 0, 1 ether);
        newMin = bound(newMin, 0, 1 ether);

        // 1) set MinSum to initialMin (before initialization) and set log file to some address (use actor)
        // SetMinSum and SetLogFile are protected by nonReentrant_ and revert if intitalized is true.
        // call SetMinSum
        c.SetMinSum(initialMin);
        // set a LogFile so Put/Collect record but not necessary; pass actor as dummy
        c.SetLogFile(address(this));
        // mark initialized
        c.Initialized();

        // observe MinSum after initialization
        uint256 before = c.MinSum();
        // sanity: should equal initialMin
        // (we do not assert here; final assert will compare before vs after)

        // 2) prepare actor with funds and perform Put to have balance >= MinSum possibly
        vm.deal(actor, deposit + 1 ether);
        vm.prank(actor);
        c.Put{value: deposit}(0);

        // 3) actor calls Collect with collectAmt; this is the relevant external entry
        vm.prank(actor);
        // wrap call to Collect to ensure we observe behavior regardless of revert
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // 4) AFTER the Collect attempt, attempt (as attacker) to call SetMinSum to newMin
        // In the reference contract this should revert because intitalized==true; in the mutant it will succeed.
        // We perform this call from a different externally controlled address (actor) to simulate an external party changing MinSum.
        vm.prank(actor);
        bool setOk;
        try c.SetMinSum(newMin) {
            setOk = true;
        } catch {
            setOk = false;
        }

        // read MinSum after the sequence
        uint256 after = c.MinSum();

        // The single assertion: In the correct contract, once initialized, MinSum cannot be changed by SetMinSum,
        // so after must equal before. The mutant that removed the revert can make setOk == true and after != before.
        assertTrue(after == before);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive c: ensure caller can set MinSum before calling Initialized()
    // Parameters: val to set, and dummyMin to check getter
    function run(uint newMin) public {
        // Precondition: we don't call Initialized(), so intitalized should be false initially.
        // Call SetMinSum to set MinSum before initialization
        c.SetMinSum(newMin);

        // Read observed MinSum
        uint observed = c.MinSum();

        // The distinguishing property: MinSum must equal the provided value (call succeeded and took effect)
        assert(observed == newMin);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint am) public payable {
        // ensure this test can call Collect: require the test contract has enough balance to cover any transfers
        require(address(this).balance >= am);
        // Precondition: contract should be uninitialized so original allows SetMinSum only when not initialized
        // We cannot read intitalized (it's not public). Instead, we rely on behavior: call Collect while expecting it to possibly send ether out.
        // Record MinSum before the call via public getter
        uint before = c.MinSum();
        // Call Collect which, in the mutant, may have caused MinSum to have been changed earlier by preventing SetMinSum before initialization.
        c.Collect(am);
