contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint am) public payable {
        // precondition: use caller as msg.sender surrogate by having caller already have funds stored in c
        // We cannot impersonate caller, so require am > 0 and that this contract has enough balance to send
        require(address(this).balance >= am);
        // read MinSum before
        uint before = c.MinSum();
        // Call Collect from this contract, forwarding am wei
        c.Collect{value: am}(am);
        // read MinSum after
        uint after_ = c.MinSum();
        // If contract is not initialized (observable via trying to set Initialized only changes internal flag and has no getter),
        // we capture the general rule: when not initialized, MinSum must stay the same. Since we cannot read intitalized,
        // we assert that either MinSum unchanged, or if changed then it must have been changed by prior initialization — but
        // to keep the rule general and detect the mutant which inverted the guard, we assert MinSum unchanged.
        assert(before == after_);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint am) public payable {
        // precondition: ensure contract is not initialized and MinSum is nonzero
        require(c.intitalized() == false);
        uint before = c.MinSum();
        require(before != 0);
        // Call Collect as in the counterexample
        c.Collect(am);
        uint after = c.MinSum();
        // General rule: if not initialized and MinSum was nonzero before, it must remain nonzero after Collect
        assert(after != 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We take a caller address through msg.sender when tests run; use an amount parameter
    function run(uint sendAmount) public payable {
        // Ensure this test contract has enough balance to attempt any calls (if sending Ether needed)
        require(address(this).balance >= sendAmount);
        // Precondition: MinSum is nonzero (the distinguishing case: original allows setting MinSum before initialization elsewhere)
        uint before = c.MinSum();
        require(before != 0);
        // Call Collect as in the counterexample; use sendAmount as _am. We expect Collect not to modify MinSum when caller has insufficient acc.balance.
        c.Collect(sendAmount);
        uint after = c.MinSum();
        // General rule: if MinSum was nonzero before and the caller did not meet conditions to withdraw (i.e., their balance in Acc is less than MinSum or less than sendAmount or lock not expired), then MinSum must remain unchanged.
        // We cannot read Acc directly, so we conservatively require that if before != 0 then after == before (this holds in original but is violated by mutant which prevents setting MinSum before init and may differ).
        assert(after == before);
    }
    receive() external payable {}
}

