import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - addr: the actor who will interact with the contract (fuzzer supplies an address); we will fund and use vm.prank
    // - putValue: value sent to Put (and fallback) to create balance
    // - lockTime: argument to Put to set unlockTime
    // - collectAmt: amount passed to Collect
    function testFuzz_property(address addr, uint256 putValue, uint256 lockTime, uint256 collectAmt) public {
        // Keep values in wide but sensible ranges to avoid trivial overflows and to ensure putValue can be funded
        vm.assume(addr != address(0));
        putValue = bound(putValue, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);
        lockTime = bound(lockTime, 0, 1 days);

        // Ensure the actor has funds to send
        vm.deal(addr, putValue + 1 ether);

        // 1) Optionally set MinSum to some value via SetMinSum before initialization (reference allows it; mutant may revert)
        // We call SetMinSum guardedly: if it reverts on mutant it won't affect this test because we only assert MinSum stays unchanged by Collect.
        // Use try/catch to avoid test revert on mutant behaviour of SetMinSum.
        try c.SetMinSum(0) {
            // ok, MinSum set to 0
        } catch {}

        // 2) Make a Put to create a balance for addr
        vm.prank(addr);
        c.Put{value: putValue}(lockTime);

        // 3) Advance time beyond unlock to allow Collect to proceed if balances meet conditions
        vm.warp(block.timestamp + lockTime + 1);

